//! 📚️ Completed replay metadata reads exact original Edit slots until each borrowed digest and index row finishes.
use crate::lifted_store::ArtifactStore;
use semio_framework_os_spr::{Edit,Mutation,OpBinary,OpText};
use semio_framework_os_store_replay::EditReplayResult;
use semio_framework_value::{ToValue,ValueError,ArtifactOwnedValueRetirementFactory,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_os_store_ledger::original_replay_metadata::{OriginalReplayMetadata,ReplayMetadataRow};
use semio_framework_os_store_replay::replay_preparation::native::history::OriginalHistorySource;
use semio_framework_value::{FactoryAuthority,RetirementDemand,retained_clone::retained_clone_grant_admits};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use std::mem::{ManuallyDrop,size_of};
use std::sync::Arc;

/// 🧳️ Metadata owns its actual roots and source loans independently of unpublished replay payloads.
pub struct OriginalReplayMetadataPreparation<M:Sync>{pub metadata:OriginalReplayMetadata,source:ManuallyDrop<Option<OriginalHistorySource<Edit<M>>>>,issuer:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>>,issuer_close:Option<FactoryAuthority>,frontier:(usize,u64,u64,[u8;32]),ordinal:usize,returning:bool,closing:bool,clear_redo:bool,selected_redo:ManuallyDrop<Option<semio_framework_os_vcs::HistoryPageStack<semio_framework_os_store_ledger::CursorRevisionRecord>>>,redo_row:usize,redo_ready:bool,redo_close:semio_framework_value::retained_clone::RetainedCloneClose,empty_redo:semio_framework_os_vcs::HistoryPageStack<semio_framework_os_store_ledger::CursorRevisionRecord>}
fn invalid(text:&'static str)->ValueError{ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,text)}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn fund(control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant,d:RetirementDemand)->Result<bool,ValueError>{if !retained_clone_grant_admits(grant,d){return Ok(false)}control.admit_turn_capacity(grant.maximum_capacity_bytes)?;control.charge(d.capacity_bytes)?;Ok(true)}
impl<M:Sync> OriginalReplayMetadataPreparation<M>{
 /// 🌱️ The enclosing funded publisher captures the same document identity and source frontier once.
 pub fn new(frontier:(usize,u64,u64,[u8;32]),identity:[u8;32],clear_redo:bool)->Self{Self{metadata:OriginalReplayMetadata::new(identity),source:ManuallyDrop::new(None),issuer:ManuallyDrop::new(None),issuer_close:None,frontier,ordinal:0,returning:false,closing:false,clear_redo,selected_redo:ManuallyDrop::new(None),redo_row:0,redo_ready:false,redo_close:Default::default(),empty_redo:semio_framework_os_vcs::HistoryPageStack::empty()}}
 /// 🪃️ A streamed abort rebuilds the applied prefix while preserving the original redo authority.
 pub(crate) fn new_stream_abort(frontier:(usize,u64,u64,[u8;32]),identity:[u8;32])->Self{let mut owner=Self::new(frontier,identity,false);owner.redo_ready=true;owner}
 /// 🏁️ Every original source and issuer must return before the publisher can expose prepared metadata.
 pub fn prepared(&self)->bool{self.metadata.prepared()&&self.source.is_none()&&self.issuer.is_none()&&self.issuer_close.is_none()&&!self.closing}
 /// 🛑️ Cancellation stops borrowed codecs before returning the original history slots.
 pub fn begin_close(&mut self){self.closing=true;self.returning=true;self.metadata.begin_close();if let Some(source)=self.source.as_mut(){source.begin_close();}}
 /// 🫙️ Terminal ownership includes private metadata, original reads and their captured issuer authority.
 pub fn terminal_is_empty(&self)->bool{self.metadata.terminal_is_empty()&&self.selected_redo.is_none()&&self.redo_close.is_empty()&&self.source.is_none()&&self.issuer.is_none()&&self.issuer_close.is_none()}
}
impl<M:Send+Sync+'static> OriginalReplayMetadataPreparation<M>{
 fn validate<P>(&self,store:&ArtifactStore<P,M>,result:Option<&EditReplayResult<P,M>>)->Result<(),ValueError>where P:ToValue,M:ToValue+Mutation<P>{let (registry,issuance,generation,revision)=self.frontier;if store.owners.snapshot_read_leases.identity()!=registry||store.log.envelope.vcs.edits.retained_issuance()!=issuance{return Err(invalid("replay metadata requires its original Store and history issuer"))}if let Some(result)=result{if store.cursor.generation!=generation||store.cursor.content_revision!=revision||result.revision!=revision||result.original_history!=Some((registry,issuance)){return Err(invalid("replay metadata original event frontier changed"))}}Ok(())}
 /// 🪡️ One turn retains, digests or returns one genuine original history row under the caller's decoder.
 pub fn advance<P>(&mut self,store:&mut ArtifactStore<P,M>,result:&EditReplayResult<P,M>,control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>where P:ToValue+Send+Sync+'static,M:ToValue+Mutation<P>+OpBinary+OpText{
  self.advance_in_order(store,result,None,control,grant)
 }
 pub(crate) fn advance_in_order<P>(&mut self,store:&mut ArtifactStore<P,M>,result:&EditReplayResult<P,M>,order:Option<&semio_framework_os_vcs::HistoryPageStack<semio_framework_os_vcs::ArtifactHistoryKey>>,control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>where P:ToValue+Send+Sync+'static,M:ToValue+Mutation<P>+OpBinary+OpText{
  if result.original_order!=order.map(|o|(o as*const _ as usize,o.len())){return Err(invalid("metadata changed its original selected edit order source"))}
  self.validate(store,Some(result))?;if result.original_decode!=control.retirement_recipient_identity().map(|recipient|(control.ledger_identity(),recipient)){return Err(invalid("replay metadata requires its original decoder ledger and recipient"))}if self.closing{return Err(invalid("closing replay metadata cannot resume preparation"))}if self.prepared(){return Ok(Default::default())}
  if let Some(selection)=result.original_selection{if !self.redo_ready{if self.selected_redo.is_none(){let d=header::<semio_framework_os_vcs::HistoryPageStack<semio_framework_os_store_ledger::CursorRevisionRecord>>();if !fund(control,grant,d)?{return Ok(Default::default())}*self.selected_redo=Some(semio_framework_os_vcs::HistoryPageStack::empty());return Ok(receipt(d))}let original=&store.cursor.revision_accumulator.redo;let length=if selection.restoring{original.len().checked_sub(1)}else{original.len().checked_add(1)}.ok_or_else(||invalid("native history redo extent changed"))?;if self.redo_row==length{let d=header::<bool>();if !fund(control,grant,d)?{return Ok(Default::default())}self.redo_ready=true;return Ok(receipt(d))}let source=if !selection.restoring&&self.redo_row==original.len(){store.cursor.revision_accumulator.applied.get(selection.position)}else{original.get(self.redo_row+usize::from(selection.restoring&&self.redo_row>=selection.redo_position))}.ok_or_else(||invalid("native history original redo record is absent"))?;let target=self.selected_redo.as_mut().unwrap();let d=RetirementDemand{capacity_bytes:target.next_push_allocation_bytes(),..header::<(semio_framework_os_store_ledger::CursorRevisionRecord,usize)>()};if !fund(control,grant,d)?{return Ok(Default::default())}target.try_push(source.clone()).map_err(|_|invalid("native history prepared redo record refused its original slot"))?;self.redo_row+=1;return Ok(receipt(d))}}
  if self.returning||self.metadata.prepared(){return self.return_source(store,grant,|d|fund(control,grant,d))}
  if self.metadata.ordinal()==result.order.len(){return self.metadata.advance::<P,M>(None,if let Some(redo)=self.selected_redo.as_ref(){redo}else if self.clear_redo{&self.empty_redo}else{&store.cursor.revision_accumulator.redo},grant,|_,_,_,_|Err(invalid("finished metadata cannot request another edit digest")),|bytes|{control.admit_turn_capacity(grant.maximum_capacity_bytes)?;control.charge(bytes)})}
  if self.issuer.is_none(){let d=store.history_edit_read_issuer_demands();if !fund(control,grant,d)?{return Ok(Default::default())}return store.admit_history_edit_read_issuer(&mut self.issuer,grant).map(|step|step.progress())}
  let ordinal=self.metadata.ordinal();let key=if let Some(order)=order{*order.get(ordinal).ok_or_else(||invalid("checkpoint metadata original key is absent"))?}else{store.original_report_key(result.original_selection,ordinal).map_err(|_|invalid("replay metadata original selected ledger key is absent"))?};
  if self.source.is_none(){let read=store.log.envelope.vcs.edits.retained_read_key(key).ok_or_else(||invalid("replay metadata original edit is absent"))?;let d=OriginalHistorySource::<Edit<M>>::constructor_demand();if !fund(control,grant,d)?{return Ok(Default::default())}if let Some((source,p))=OriginalHistorySource::admit(read,store.log.envelope.vcs.edits.retained_read_issuer(read)?.unwrap_or(self.issuer.as_ref().unwrap()),grant)?{*self.source=Some(source);self.ordinal=ordinal;return Ok(p)}return Ok(Default::default())}
  let source=self.source.as_mut().unwrap();if source.borrow_original().is_err(){let d=source.root_demands(&store.log.envelope.vcs.edits)?;if !fund(control,grant,d)?{return Ok(Default::default())}return source.advance_root(&mut store.log.envelope.vcs.edits,grant).map(|step|step.progress())}
  let original=source.borrow_original()?;let edit=original.get();if result.order.get(ordinal)!=Some(&edit.id){return Err(invalid("replay metadata changed its original applied edit order"))}
  let inverse=if ordinal>=result.from{let row=result.rebased_inverse.get(ordinal-result.from).ok_or_else(||invalid("completed replay omitted its original rebased inverse row"))?;if row.0!=edit.id{return Err(invalid("completed replay inverse row differs from its original edit"))}&row.1}else{&*edit.inverse};
  let wire=store.log.operation_wire.as_ref().ok_or_else(||invalid("replay metadata original operation codec is absent"))?;
  let p=self.metadata.advance::<P,M>(Some(ReplayMetadataRow{ledger_key:key,edit,inverse,supersessions:&result.supersessions,flags:&result.unit_flags,previous_flags:&store.cursor.revision_accumulator.unit_flags}),if let Some(redo)=self.selected_redo.as_ref(){redo}else if self.clear_redo{&self.empty_redo}else{&store.cursor.revision_accumulator.redo},grant,|cursor,edit,inverse,g|wire.advance_history_digest(cursor,edit,inverse,g),|bytes|{control.admit_turn_capacity(grant.maximum_capacity_bytes)?;control.charge(bytes)})?;
  if self.metadata.ordinal()!=ordinal{self.returning=true;source.begin_close();}Ok(p)
 }
 fn return_source<P>(&mut self,store:&mut ArtifactStore<P,M>,grant:RetainedCloneGrant,mut fund:impl FnMut(RetirementDemand)->Result<bool,ValueError>)->Result<RetainedCloneProgress,ValueError>where P:ToValue,M:ToValue+Mutation<P>{
  if let Some(source)=self.source.as_mut(){source.begin_close();if source.terminal_is_empty(){let d=header::<Option<OriginalHistorySource<Edit<M>>>>();if !fund(d)?{return Ok(Default::default())}self.source.take();self.returning=false;return Ok(receipt(d))}let d=source.close_demands(&store.log.envelope.vcs.edits,grant.maximum_copy_bytes)?;if !fund(d)?{return Ok(Default::default())}return source.close_step(&mut store.log.envelope.vcs.edits,grant).map(|step|step.progress())}
  if let Some(issuer)=self.issuer_close.as_mut(){if issuer.terminal_is_empty(){let d=header::<Option<FactoryAuthority>>();if !fund(d)?{return Ok(Default::default())}self.issuer_close=None;return Ok(receipt(d))}let d=issuer.demands(grant.maximum_copy_bytes)?;if !fund(d)?{return Ok(Default::default())}return issuer.step(grant).map(|step|step.progress())}
  if self.issuer.is_some(){let d=header::<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>();if !fund(d)?{return Ok(Default::default())}self.issuer_close=Some(FactoryAuthority::new(self.issuer.take().unwrap()));return Ok(receipt(d))}Ok(Default::default())
 }
 /// 📏️ Quotes the exact next original source return or private metadata close without changing custody.
 pub fn close_demands<P>(&self,store:&ArtifactStore<P,M>,body:usize)->Result<RetirementDemand,ValueError>where P:ToValue,M:ToValue+Mutation<P>{self.validate(store,None)?;if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(header::<Option<OriginalHistorySource<Edit<M>>>>())}else{source.close_demands(&store.log.envelope.vcs.edits,body)}}if let Some(issuer)=self.issuer_close.as_ref(){return if issuer.terminal_is_empty(){Ok(header::<Option<FactoryAuthority>>())}else{issuer.demands(body)}}if self.issuer.is_some(){return Ok(header::<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>())}if !self.redo_close.is_empty(){return self.redo_close.demands(body)}if self.selected_redo.is_some(){return self.redo_close.next_owner_demands::<semio_framework_os_vcs::HistoryPageStack<semio_framework_os_store_ledger::CursorRevisionRecord>>(true,&None,body)}self.metadata.close_demands(body)}
 /// ♻️ Returns original reads before retiring private or displaced metadata through actual admitted turns.
 pub fn close_step<P>(&mut self,store:&mut ArtifactStore<P,M>,control:&mut dyn semio_framework_value::OriginalRetirementControl,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>where P:ToValue,M:ToValue+Mutation<P>{self.validate(store,None)?;self.begin_close();if self.source.is_some()||self.issuer.is_some()||self.issuer_close.is_some(){return self.return_source(store,grant,|d|{if !retained_clone_grant_admits(grant,d){return Ok(false)}control.charge(d.capacity_bytes)?;Ok(true)}).map(RetainedCloneStep::Progress)}if !self.redo_close.is_empty()||self.selected_redo.is_some(){let d=self.close_demands(store,grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.charge(d.capacity_bytes)?;if !self.redo_close.is_empty(){return self.redo_close.step_granted(grant)}return Ok(self.redo_close.begin_granted(&mut self.selected_redo,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}let d=self.metadata.close_demands(grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.charge(d.capacity_bytes)?;self.metadata.close_step(grant)}
}
impl<M:Sync> Drop for OriginalReplayMetadataPreparation<M>{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"completed replay metadata retains original source or private roots");}}
